import rawEntries from '../../data/pokedex.json';
import rawInitialStatuses from '../../data/initial-statuses.json';
import { BUNDLED_GENERATIONS, buildDexes, findDex, type DexDefinition, type DexId } from './listQuery';
import type { AddedEntry, EntryCategory, PokedexEntry, ShinyStatus, StatusMap } from './model';

/**
 * Reference data generated by `npm run import:build`. The JSON is produced by
 * our own script from the shared model, so the cast only narrows string
 * literals that TypeScript widens when importing JSON.
 */
export const BUNDLED_ENTRIES = rawEntries as PokedexEntry[];
export const INITIAL_STATUSES = rawInitialStatuses as StatusMap;

const SPRITE_ROOT = `${import.meta.env.BASE_URL}sprites`;

/** URL of a bundled entry's HOME sprite, generated by `npm run import:sprites`. */
export function spriteUrl(id: string, variant: 'normal' | 'shiny'): string {
  return `${SPRITE_ROOT}/${variant}/${id}.webp`;
}

/**
 * Every entry the app knows: the bundled data followed by species added
 * later from PokéAPI. Built once per change of the added species.
 */
export interface Catalog {
  entries: readonly PokedexEntry[];
  /** Generations present in the catalog, ascending. */
  generations: readonly number[];
  dexes: readonly DexDefinition[];
  /** Highest National Pokédex number known, used to detect new species. */
  maxDex: number;
  getEntry: (id: string) => PokedexEntry | undefined;
  /** Previous and next entries in display order, for the detail page navigation. */
  getNeighbours: (id: string) => { previous?: PokedexEntry; next?: PokedexEntry };
  getDex: (id: DexId) => DexDefinition;
  /** Sprite URL, or null when an added species has no sprite on PokéAPI yet. */
  spriteSrc: (id: string, variant: 'normal' | 'shiny') => string | null;
}

export function buildCatalog(added: readonly AddedEntry[]): Catalog {
  const bundledIds = new Set(BUNDLED_ENTRIES.map((entry) => entry.id));
  // Added species come after every bundled entry: they are new National
  // Pokédex numbers, so appending keeps the Pokédex order. Once a later import
  // bundles them, the bundled copy (with local sprites) takes over.
  const extra = added.filter((entry) => !bundledIds.has(entry.id)).sort((a, b) => a.dex - b.dex);
  const entries: PokedexEntry[] = [...BUNDLED_ENTRIES, ...extra];
  const remoteSprites = new Map(extra.map((entry) => [entry.id, entry.spriteUrls]));

  const entryById = new Map(entries.map((entry) => [entry.id, entry]));
  const indexById = new Map(entries.map((entry, index) => [entry.id, index]));
  const generations = [...new Set([...BUNDLED_GENERATIONS, ...entries.map((entry) => entry.generation)])].sort(
    (a, b) => a - b,
  );
  const dexes = buildDexes(generations);

  return {
    entries,
    generations,
    dexes,
    maxDex: entries.reduce((max, entry) => Math.max(max, entry.dex), 0),
    getEntry: (id) => entryById.get(id),
    getNeighbours: (id) => {
      const index = indexById.get(id);
      return index === undefined ? {} : { previous: entries[index - 1], next: entries[index + 1] };
    },
    getDex: (id) => findDex(dexes, id),
    spriteSrc: (id, variant) => {
      const remote = remoteSprites.get(id);
      return remote ? remote[variant] : spriteUrl(id, variant);
    },
  };
}

/** The catalog without any added species: the default outside a provider, and in tests. */
export const BUNDLED_CATALOG = buildCatalog([]);

export function formatDexNumber(dex: number): string {
  return `#${String(dex).padStart(4, '0')}`;
}

/** Short badge shown on regional forms; other categories carry their form in the name. */
export const CATEGORY_BADGES: Partial<Record<EntryCategory, string>> = {
  alola: 'Alola',
  galar: 'Galar',
  hisui: 'Hisui',
  paldea: 'Paldea',
};

export const STATUS_LABELS: Record<ShinyStatus, string> = {
  obtained: 'Obtenu',
  'to-farm': 'À farm',
  locked: 'Shiny lock',
};

export interface StatusCounts {
  total: number;
  obtained: number;
  toFarm: number;
  locked: number;
}

/**
 * Counts statuses over the given entries. Shiny-locked entries stay in the
 * total, matching how the original Sheet computed its percentages.
 */
export function countStatuses(entries: readonly PokedexEntry[], statuses: ReadonlyMap<string, ShinyStatus>): StatusCounts {
  const counts: StatusCounts = { total: entries.length, obtained: 0, toFarm: 0, locked: 0 };
  for (const entry of entries) {
    const status = statuses.get(entry.id);
    if (status === 'obtained') counts.obtained += 1;
    else if (status === 'locked') counts.locked += 1;
    else counts.toFarm += 1;
  }
  return counts;
}

/** Next status for the list's one-tap toggle (shiny-locked entries are not toggled there). */
export function toggledStatus(status: ShinyStatus): ShinyStatus {
  return status === 'obtained' ? 'to-farm' : 'obtained';
}
